import{z as d,x as m,o as e,c as n,q as t,j as o,D as E,d as r,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"刻蚀负载效应","description":"","frontmatter":{"title":"刻蚀负载效应","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etch-loading-effect.md","filePath":"litho/etch-loading-effect.md","lastUpdated":1791413859000}'),s={name:"litho/etch-loading-effect.md"};function B(p,a,h,u,c,C){const A=m("Mermaid");return e(),n("div",null,[a[2]||(a[2]=t('<h1 id="刻蚀负载效应" tabindex="-1">刻蚀负载效应 <a class="header-anchor" href="#刻蚀负载效应" aria-label="Permalink to &quot;刻蚀负载效应&quot;">​</a></h1><div class="epigraph"><p>同一食谱，开阔区把自由基吃光，密区抢通量，边缘阵列速率另走一套；负载把布局写成 AEI 的长程邻域。</p><footer>—— 对照宏负荷 / 微负荷产线通称；[深宽比与负荷](/litho/etch-loading-ar) 已给几何定义</footer></div><p><a href="/litho/anisotropy-passivation">上一课</a>指出钝化随开口率变。缺口是集成尺度：芯片上 SRAM 阵列、逻辑、划片槽、dummy 的开口率差，把 CD 和剖面拉成一张密度图。<a href="/litho/etch-loading-ar">ARDE 课</a> 已钉宏/微负荷；本课不重写到达概率，而钉<strong>设计填充、dummy 与腔体匹配如何管理负载</strong>。刻蚀偏置如何回写 OPC，留给<a href="/litho/etch-bias-opc-loop">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宏负荷：晶圆或场级开放面积大，中性浓度下降，全球速率降。微负荷：局部密度，特征互相抢。阵列边缘：介于宏与微之间，SRAM 课已警告 dummy。填充（dummies）和槽密度规则有一截就是买均匀通量，不是为了好看。腔体与静电吸盘温度、气体注入位置再叠一张径向指纹，与布局负载不可互替。</p><p>缺口是<strong>合同：谁补负载</strong>。只让 OPC 核吃密度，腔体指纹漂了核就过时；只拧腔体，换产品开口率仍爆。要分层：设计密度窗 + 核 + 腔体 APC。</p><p><span class="marginnote">术语翻译：开口率就是这片布局里「透空」的面积占比——刻蚀气体真正能接触到的部分。例如 \\(1\\,\\mathrm{mm}^2\\) 内金属占 \\(0.3\\,\\mathrm{mm}^2\\)，开口率就是 \\(30\\%\\)。SRAM 阵列、划片槽、大电源开口率相差悬殊，同一片晶圆上的刻蚀速率因此分道扬镳。</span></p>',7)),(e(),o(l,null,{default:E(()=>[i(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22AEI%20%E5%81%8F%E5%B7%AE%E8%B6%85%E7%AA%97%22%5D%20--%3E%20S%7B%22%E5%81%8F%E5%B7%AE%E8%B7%9F%E7%9D%80%E4%BB%80%E4%B9%88%E8%B5%B0%22%7D%0A%20%20S%20--%20%22%E9%9A%8F%E5%B8%83%E5%B1%80%E5%BC%80%E5%8F%A3%E7%8E%87%22%20--%3E%20D%5B%22%E8%AE%BE%E8%AE%A1%E4%BE%A7%EF%BC%9A%E5%AF%86%E5%BA%A6%E7%AA%97%E4%B8%8E%20dummy%22%5D%0A%20%20S%20--%20%22%E9%9A%8F%E5%BE%84%E5%90%91%E4%BD%8D%E7%BD%AE%22%20--%3E%20C%5B%22%E8%85%94%E4%BD%93%E4%BE%A7%EF%BC%9A%E6%B0%94%E6%B5%81%E6%B8%A9%E5%BA%A6%20APC%22%5D%0A%20%20S%20--%20%22%E9%9A%8F%E5%AF%86%E5%BA%A6%E6%96%9C%E7%8E%87%22%20--%3E%20K%5B%22%E6%A8%A1%E5%9E%8B%E4%BE%A7%EF%BC%9A%E5%88%BB%E8%9A%80%E6%A0%B8%E5%AF%86%E5%BA%A6%E9%A1%B9%22%5D%0A%20%20D%20--%3E%20VER%5B%22%E4%BA%A7%E5%93%81%E6%8D%A2%E7%89%88%E5%BC%80%E5%8F%A3%E7%8E%87%E5%A4%A7%E5%8F%98%E6%97%B6%E9%87%8D%E9%AA%8C%E8%AF%81%22%5D%0A%20%20C%20--%3E%20VER%0A%20%20K%20--%3E%20VER%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="dummy-不是免费金属" tabindex="-1">dummy 不是免费金属 <a class="header-anchor" href="#dummy-不是免费金属" aria-label="Permalink to &quot;dummy 不是免费金属&quot;">​</a></h3><p>金属 dummy 影响 CMP（下下课）和电容；介质 dummy 影响局部负荷。规则要声明电气是否连接、是否允许在模拟区。乱填会制造新的微负荷周期，匹配模板里出现「dummy 引起的杀手」。</p><p><span class="marginnote">常见误区：把 dummy 当成「凑密度的小方块」。它其实要同时过三关——刻蚀负荷、CMP 碟形、电学耦合电容；填得不讲周期，反而制造出新的微负荷条纹，把原本合格的区域变成杀手区。</span></p><p><span class="marginnote">划片槽和大开口是宏负荷源。PWQ 若只用密线场，会漏掉产品真实开口率下的食谱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>量：开口率图、AEI CD 对密度、径向指纹。动作：密度规则与填充；刻蚀核多层半径（短程 + 长程）；腔体气流/温度匹配。与 <a href="/litho/cdu-etch-bias">CDU 刻蚀偏置</a> 衔接：全场 CDU 往往是负载指纹而不是镜头。产品换版开口率大变，要重验证食谱，而不是只重跑 OPC。</p><p>开口率图应用与 OPC 同一层的设计多边形生成，并含 dummy。用「芯片面积」当宏负荷代理会漏掉划片槽和大开口。腔体径向指纹要在固定开口率的测试片上量，才能和布局负荷分账。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中性消耗 \\(\\propto\\) 开放面积 × 反应概率；扩散补给跟不上则局部浓度降。聚合物前体同样被布局调制，于是钝化与选择比都随密度走——负载不只是「慢一点」，而是剖面形状一起变。长程核能近似平滑密度，吃不掉腔体不对称和晶圆边缘（后课部分场）。</p>',9)),(e(),o(l,null,{default:E(()=>[i(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E5%BC%80%E5%8F%A3%E7%8E%87%E5%B8%83%E5%B1%80%22%5D%20--%3E%20MICRO%5B%22%E5%BE%AE%E8%B4%9F%E8%8D%B7%22%5D%0A%20%20LAY%20--%3E%20MACRO%5B%22%E5%AE%8F%E8%B4%9F%E8%8D%B7%22%5D%0A%20%20CH%5B%22%E8%85%94%E4%BD%93%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20AEI%5B%22AEI%20CD%20%2F%20%E5%89%96%E9%9D%A2%22%5D%0A%20%20MICRO%20--%3E%20AEI%0A%20%20MACRO%20--%3E%20AEI%0A%20%20DUM%5B%22dummy%20%2F%20%E5%AF%86%E5%BA%A6%E7%AA%97%22%5D%20--%3E%20LAY%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>布局开口率与腔体指纹在 AEI 上相加。dummy 只能改前者；径向不对称要回腔体，禁止让 OPC 核去拟合喷淋头。</p><p><span class="marginnote">为什么重要：长程密度核能平滑布局负载，却对腔体径向不对称无能为力。若放任 OPC 核去拟合喷淋头缺陷，换一台腔体或换晶圆位置，核立刻失效，版本管理也随之报废——分账必须在计量阶段就做完。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重推 ARDE 公式。不把某产品的 dummy 规则当 SEMI 标准。等离子体颗粒与负载是不同机制。</p><p>后课默认：负载由设计密度 + 核 + 腔体分层管理。下一课把测到的偏置闭环回 OPC，而不是每个班次拧激光。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>负载是布局调制的通量与钝化，CD 与剖面一起走。</li><li>dummy 与密度窗是设计侧补丁，带电学代价。</li><li>腔体指纹与布局负荷要分开计量。</li><li>出处：宏/微负荷通称；刻蚀工程与计算光刻密度核。</li></ul>',7))])}const f=d(s,[["render",B]]);export{_ as __pageData,f as default};
